/* Braun DNA — Dieter Rams functionalism: warm gray, black text, signal-orange dot */
.theme-braun-dna {
  --bg: oklch(0.9 0.006 85);
  --surface: oklch(0.945 0.005 85);
  --surface-2: oklch(0.86 0.007 85);
  --fg: oklch(0.15 0.004 85);
  --fg-muted: oklch(0.46 0.005 85);
  --accent: oklch(0.756 0.155 73.2);
  --accent-fg: oklch(0.99 0 0);
  --accent-2: oklch(0.15 0.004 85);
  --line: oklch(0.74 0.006 85);
  --success: oklch(0.55 0.12 150);
  --warning: oklch(0.75 0.15 85);
  --danger: oklch(0.55 0.2 28);

  --radius: 0.125rem;
  --radius-sm: 0.0625rem;
  --radius-lg: 0.25rem;
  --radius-pill: 9999px;

  --shadow-1: none;
  --shadow-2: 0 1px 2px oklch(0 0 0 / 10%);
  --shadow-3: 0 6px 16px -10px oklch(0 0 0 / 25%);
  --glow: 0 0 0 2px var(--accent);

  --border-width: 1px;
  --blur-amount: 0px;

  --font-display: "Archivo", "Helvetica Neue", sans-serif;
  --font-body: "Archivo", sans-serif;
  --font-mono: "IBM Plex Mono", ui-monospace, monospace;

  --tracking-display: -0.01em;
  --label-transform: uppercase;
  --label-tracking: 0.1em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
  line-height: 1.55;
}

.theme-braun-dna h1,
.theme-braun-dna h2,
.theme-braun-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
  font-weight: 500;
  line-height: 1.1;
}

.theme-braun-dna label,
.theme-braun-dna th {
  text-transform: var(--label-transform);
  letter-spacing: var(--label-tracking);
  font-size: 0.6875rem;
}

/* signature */
.theme-braun-dna h1 { font-weight: 500; }
.theme-braun-dna h2::before { content: ""; display: inline-block; width: 0.45em; height: 0.45em; border-radius: 50%; background: var(--accent); margin-right: 0.45em; }
.theme-braun-dna button { letter-spacing: 0.02em; }

/* alt mode: auto-derived dark variant */
.theme-braun-dna.alt-mode {
  --bg: oklch(0.145 0.006 85.0);
  --surface: oklch(0.185 0.006 85.0);
  --surface-2: oklch(0.225 0.006 85.0);
  --fg: oklch(0.97 0.005 90);
  --fg-muted: oklch(0.70 0.01 90);
  --line: oklch(1 0 0 / 14%);
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
}

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
